let state=null,admin=false,csrf=null,currentRound=1,tabName='table',saving=false;const dirty=new Set(),timers=new Map();
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,body){const res=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-CSRF-Token':csrf||''}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await res.json();if(!res.ok)throw Error(data.error||'Kunne ikke hente data.');return data}
function error(message){$('#error').textContent=message;$('#error').hidden=!message}
function statusLabel(m){return {upcoming:'Ikke startet',live:'● Pågår',finished:'Avsluttet'}[m.status]}
function score(v){return v===null?'–':v}
function rowTeam(name){return `${crest(name)}<span>${esc(name)}</span>`}
function selectTab(name){tabName=name;document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==name);document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-current',b.dataset.tab===name?'page':'false'))}
function render(){if(!state)return;$('#standings').innerHTML=state.table.map((r,i)=>`<tr class="pair-${Math.floor(i/2)}"><td>${i+1}</td><td><span class="team-label">${rowTeam(r.name)}</span></td><td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.gf}–${r.ga}</td><td>${r.gd>0?'+':''}${r.gd}</td><td>${r.pts}</td></tr>`).join('');const live=state.matches.filter(m=>m.status==='live').length;$('#live-indicator').textContent=live?`${live} kamp${live===1?'':'er'} pågår`:'Ingen kamper pågår';$('#live-indicator').classList.toggle('live',live>0);const completed=state.matches.filter(m=>m.status==='finished'&&m.hs!==null&&m.aws!==null).length;$('#progress').textContent=`${completed} / ${state.matches.length} kamper registrert og avsluttet`;let next=state.matches.filter(m=>m.status==='live');if(!next.length)next=state.matches.filter(m=>m.status==='upcoming');$('#upcoming').innerHTML=next.slice(0,3).map(m=>`<div class="fixture"><div class="fixture-meta"><span>${m.start}–${m.end} · Bane ${m.pitch}</span><span>Runde ${m.round}</span></div><div class="fixture-team">${rowTeam(m.home)}<b>${m.status==='live'?score(m.hs):''}</b></div><div class="fixture-team">${rowTeam(m.away)}<b>${m.status==='live'?score(m.aws):''}</b></div>${m.provisional?'<p class="small-note">Foreløpig oppsett</p>':''}</div>`).join('')||'<div class="fixture">Alle kampene er avsluttet.</div>';$('#auth-button').textContent=admin?'Logg ut':'Admin';if(!dirty.size&&!$('#match-cards').contains(document.activeElement))renderCards()}
function renderCards(){if(!state)return;$('#round').value=currentRound;document.querySelectorAll('[data-round]').forEach(b=>b.classList.toggle('active',Number(b.dataset.round)===currentRound));const ms=state.matches.filter(m=>m.round===currentRound);$('#round-description').textContent=currentRound===10?`Plasseringskamper kl. 13.35–13.50 · Finale kl. 13.55–14.10. ${state.seeded?'Motstanderne er låst etter seriespillet. Senere rettelser i serietabellen endrer ikke dette oppsettet.':'Motstanderne er foreløpige og følger tabellen frem til alle serieresultater er klare.'}`:`10. oktober · kl. ${ms[0].start}–${ms[0].end} · ${ms.length} kamper. ${admin?'Endringer lagres automatisk.':''}`;$('#match-cards').innerHTML=ms.map(m=>{const editable=admin&&!m.provisional;const pair=m.kind==='playoff'?`${m.ranks[0]}. mot ${m.ranks[1]}. plass`:'';let winner=m.winner;if(m.status==='finished'&&m.hs!==null&&m.aws!==null&&m.hs!==m.aws)winner=m.hs>m.aws?m.home:m.away;return `<article class="match ${m.status}" data-id="${m.id}"><div class="match-header"><span>${m.start}–${m.end} · Bane ${m.pitch}</span><span class="status">${statusLabel(m)}</span></div>${m.kind==='playoff'?`<h3>${m.ranks[1]===1?'Finale':m.ranks[1]===3?'Bronsekamp':`Kamp om ${m.ranks[1]}. plass`}</h3><p class="small-note">${pair}${m.provisional?' · foreløpig':''}</p>`:''}${[['home','hs'],['away','aws']].map(([team,field])=>`<label class="score-row">${rowTeam(m[team])}${editable?`<input aria-label="${esc(m.home)} mot ${esc(m.away)}: mål ${esc(m[team])}" data-field="${field}" type="number" min="0" max="99" step="1" inputmode="numeric" value="${m[field]??''}" placeholder="–">`:`<b>${score(m[field])}</b>`}</label>`).join('')}${editable?`<div class="admin-controls"><label>Kampstatus<select data-field="mode" aria-label="Status ${esc(m.home)} mot ${esc(m.away)}">${[['auto','Automatisk etter klokkeslett'],['upcoming','Ikke startet'],['live','Pågår'],['finished','Avsluttet']].map(([v,l])=>`<option value="${v}" ${v===m.mode?'selected':''}>${l}</option>`).join('')}</select></label>${m.kind==='playoff'?`<label>Vinner ved uavgjort<select data-field="winner"><option value="">Ikke avgjort</option>${[m.home,m.away].map(t=>`<option ${m.winner===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`:''}<button class="primary" data-save="${m.id}">Lagre resultat</button><span class="small-note save-message" role="status">Lagret på serveren</span></div>`:''}${m.status==='finished'&&(m.hs===null||m.aws===null)?'<p class="small-note">Avsluttet — venter på resultat.</p>':''}${m.kind==='playoff'&&m.status==='finished'&&m.hs!==null&&m.aws!==null?`<p class="winner">${winner?'Vinner: '+esc(winner):'Uavgjort — venter på avgjørelse'}</p>`:''}</article>`}).join('')}
async function saveCard(id){clearTimeout(timers.get(id));if(saving){timers.set(id,setTimeout(()=>saveCard(id),200));return}const card=document.querySelector(`[data-id="${id}"]`);if(!card||!dirty.has(id))return;const inputs=[...card.querySelectorAll('input')];if(inputs.some(i=>!i.checkValidity())){card.querySelector('.save-message').textContent='Bruk hele mål mellom 0 og 99.';return}const m=state.matches.find(m=>m.id===id);const val=f=>card.querySelector(`[data-field="${f}"]`)?.value;const body={id,hs:val('hs')===''?null:Number(val('hs')),aws:val('aws')===''?null:Number(val('aws')),mode:val('mode'),winner:val('winner')||null,version:m.version};if(body.hs!==body.aws)body.winner=null;saving=true;card.querySelector('.save-message').textContent='Lagrer …';try{state=await api('/api/score',body);dirty.delete(id);card.querySelector('.save-message').textContent='Lagret';error('');render()}catch(e){error(e.message);card.querySelector('.save-message').textContent='Ikke lagret. Rett feilen eller last siden på nytt.'}finally{saving=false}}
$('#match-cards').addEventListener('input',e=>{const card=e.target.closest('[data-id]');if(!card)return;const id=Number(card.dataset.id);dirty.add(id);clearTimeout(timers.get(id));timers.set(id,setTimeout(()=>saveCard(id),550))});$('#match-cards').addEventListener('change',e=>{if(e.target.tagName==='SELECT'){const id=Number(e.target.closest('[data-id]').dataset.id);dirty.add(id);saveCard(id)}});$('#match-cards').addEventListener('click',e=>{const b=e.target.closest('[data-save]');if(b){const id=Number(b.dataset.save),m=state.matches.find(x=>x.id===id);$('#confirm-copy').textContent=`Låse inn ${m.home} ${score(m.hs)}–${score(m.aws)} ${m.away}? Resultatet blir synlig for alle.`;$('#confirm-score').showModal();$('#confirm-save').onclick=()=>{dirty.add(id);saveCard(id)}}});
function changeRound(r){if(dirty.size){error('Vent til endringene er lagret før du bytter runde.');$('#round').value=currentRound;return}currentRound=r;renderCards()}
$('#round').innerHTML=Array.from({length:10},(_,i)=>`<option value="${i+1}">${i===9?'10 · Sluttspill':'Runde '+(i+1)}</option>`).join('');$('#round-tabs').innerHTML=Array.from({length:10},(_,i)=>`<button data-round="${i+1}" class="${i===0?'active':''}">${i===9?'10 · Sluttspill':i+1}</button>`).join('');$('#round').addEventListener('change',e=>changeRound(Number(e.target.value)));$('#round-tabs').addEventListener('click',e=>{if(e.target.dataset.round)changeRound(Number(e.target.dataset.round))});document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>selectTab(b.dataset.tab)));
$('#auth-button').addEventListener('click',async()=>{if(admin){if(dirty.size){error('Lagre endringene før du logger ut.');return}try{await api('/api/logout',{});admin=false;csrf=null;render();renderCards()}catch(e){error(e.message)}}else $('#login-dialog').showModal()});$('.close').addEventListener('click',()=>$('#login-dialog').close());$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;try{const s=await api('/api/login',{username:form.username.value,password:form.password.value});admin=s.admin;csrf=s.csrf;form.reset();$('#login-error').textContent='';$('#login-dialog').close();render();renderCards();selectTab('matches')}catch(e){$('#login-error').textContent=e.message}finally{button.disabled=false}});
async function refresh(){if(saving||dirty.size)return;try{state=await api('/api/state');render();$('#connection-status').textContent='Oppdatert '+new Date(state.serverTime).toLocaleTimeString('nb-NO',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Europe/Oslo'});error('')}catch(e){$('#connection-status').textContent='Frakoblet · prøver igjen';error('Kunne ikke hente oppdateringer. Viser sist mottatte resultater.')}}
(async()=>{try{const s=await api('/api/session');admin=s.admin;csrf=s.csrf}catch(e){}await refresh();setInterval(refresh,5000)})();
const pixelImages=['haaland-wrath.png','haaland-robot.gif','messi-bg.png','puskas-awards-nominees-3-the-winner-1.png','lautaro-crowd.png'];
function setUpFinalTouches(){const picked='pixel/'+pixelImages[Math.floor(Math.random()*pixelImages.length)];const load=$('#loader-pixel'),hero=$('#hero-pixel');if(load)load.src=picked;if(hero)hero.src=picked;setTimeout(()=>$('#load-bar').style.width='100%',30);setTimeout(()=>$('#loader').classList.add('done'),3000);if(!state)return;const teams=state.config.teams;const selector=$('#form-team'),follow=$('#follow-team');selector.innerHTML=teams.map(t=>`<option>${t}</option>`).join('');follow.innerHTML=teams.map(t=>`<option>${t}</option>`).join('');const saved=localStorage.getItem('konfaction-follow');if(saved){$('#follow-button').hidden=false;$('#follow-button').textContent=`Følger ${saved}`;selector.value=saved}selector.onchange=renderForm;$('#follow-button').onclick=()=>$('#follow-dialog').showModal();$('#follow-later').onclick=()=>$('#follow-dialog').close();$('#follow-dialog .close').onclick=()=>$('#follow-dialog').close();$('#follow-form').onsubmit=e=>{e.preventDefault();const team=follow.value;localStorage.setItem('konfaction-follow',team);$('#follow-button').hidden=false;$('#follow-button').textContent=`Følger ${team}`;selector.value=team;if($('#notification-opt').checked&&'Notification'in window)Notification.requestPermission();$('#follow-dialog').close();renderForm()};renderForm()}
function renderForm(){if(!state||!$('#form-team'))return;const team=$('#form-team').value||state.config.teams[0];const games=state.matches.filter(m=>m.kind==='league'&&(m.home===team||m.away===team)&&m.hs!==null&&m.aws!==null&&m.status!=='upcoming').slice(-5);const marks=games.map(m=>{const mine=m.home===team?m.hs:m.aws,other=m.home===team?m.aws:m.hs;return `<span class="form-mark ${mine>other?'win':mine<other?'loss':'draw'}">${mine>other?'S':mine<other?'T':'U'}</span>`}).join('')||'<span class="small-note">Ingen registrerte kamper ennå.</span>';$('#form-card').innerHTML=`<div class="form-team">${rowTeam(team)}<span>Fem siste</span></div><div class="form-marks">${marks}</div>`}
const originalRefresh=refresh;refresh=async function(){await originalRefresh();renderForm()};setTimeout(setUpFinalTouches,100);
